window.docContents[112].resolve({"/Elliptic-Equations/#PDEAtlas--Elliptic-Equations--Coverage-and-Open-Problems--Elliptic-Coverage-and-Open-Problems":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"PDEAtlas\u0009Elliptic Equations\u0009Coverage and Open Problems","header":"5.7.1. Elliptic Coverage and Open Problems","id":"/Elliptic-Equations/#PDEAtlas--Elliptic-Equations--Coverage-and-Open-Problems--Elliptic-Coverage-and-Open-Problems"},"/Elliptic-Equations/#PDEAtlas--Elliptic-Equations--Coverage-and-Open-Problems--Elliptic-Coverage-and-Open-Problems--Weak-boundary-value-problems--Prescribed-Sobolev-boundary-values":{"contents":"On a bounded set in positive dimension, every supplied\n admits a solution in\n for a measurable monotone hemicontinuous\ngradient flux with linear growth and a quadratic coercive lower bound,\ntogether with a measurable continuous monotone reaction of linear growth.\nThe monotonicity and continuity assumptions hold almost everywhere in space.\nGrowth offsets belong to , the coercivity offset is integrable,\nand the forcing is a continuous dual load on .\n\nStrict monotonicity of the flux gives uniqueness in this boundary class.\nThe boundary condition is the Sobolev condition .\n\n","context":"PDEAtlas\u0009Elliptic Equations\u0009Coverage and Open Problems\u0009Elliptic Coverage and Open Problems\u0009Weak boundary-value problems","header":"5.7.1.2.4. Prescribed Sobolev boundary values","id":"/Elliptic-Equations/#PDEAtlas--Elliptic-Equations--Coverage-and-Open-Problems--Elliptic-Coverage-and-Open-Problems--Weak-boundary-value-problems--Prescribed-Sobolev-boundary-values"}});